        if (!document.targetLanguages().contains(language)) throw unprocessable(...);
        String term = normalizeTermText(input.term());
        if (term.isEmpty()) throw unprocessable("术语规范化后为空");
        for (String rawAllowed : input.allowedTranslations()) {
            String allowed = normalizeTermText(rawAllowed);
            if (allowed.isEmpty()) throw unprocessable(...);
            if (!seen.add(List.of(term, language, allowed))) throw unprocessable("冻结条目重复: ...");
            entries.add(new TermFreezeEntryRow(term, language, allowed));
