        throw ApiException.freezeConflict("当前文档版本已存在有效冻结: " + active.get().freezeVersion());
    }
    String freezeKey = computeFreezeKey(documentId, document.draftVersion(), operator, entries);
    Optional<TermFreezeRow> existing = repository.findFreezeByKey(freezeKey);
