    int freezeVersion = repository.maxFreezeVersion(documentId) + 1;
    repository.insertTermFreeze(documentId, new TermFreezeRow(freezeVersion, document.draftVersion(), "ACTIVE", freezeKey, operator));
    for (entry : entries) repository.insertTermFreezeEntry(documentId, freezeVersion, entry);
